#!/usr/bin/env bash
# Collect the materials generated by individually executed plotting scripts.
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONDA_ENV="${CONDA_ENV-virtual_env}"
if [[ -n "${CONDA_ENV}" ]]; then
    python_cmd=(conda run --no-capture-output -n "${CONDA_ENV}" python)
else
    python_cmd=(python)
fi
exec "${python_cmd[@]}" "${SCRIPT_DIR}/run_paper_figures.py" \
    --collect-from "${SCRIPT_DIR}/../figure/materials" "$@"
